window.quietWords = (P) => {
 const SURF = [['tag', '#cbar'], ['toast', '#toast'], ['hint', '.hint,#' + P + '-hint'], ['overlay', '#' + P + '-prov,#' + P + '-kv-panel,#insp,.pop,#net'], ['cardOpen', '#' + P + '-card'], ['cardRest', '#' + P + '-dock,#' + P + '-guide'], ['queue', '.bl'], ['status', '.br'], ['chrome', '.fl.tl,.fl.tc,.fl.tr,#nav'], ['replay', '#rpdeck,.watermark'], ['plant', '#stage,.' + P + '-mark,#' + P + '-witness-edges']];
 const ISLANDS = '.fl,#nav,#cbar,#toast.on,#' + P + '-card,#' + P + '-dock,#' + P + '-guide,#' + P + '-prov,#' + P + '-kv-panel,.pop.open,#insp.open,#rpdeck';
 const shown = (e) => { for (let n = e, o = 1; n && n.nodeType === 1; n = n.parentElement) { const cs = getComputedStyle(n); if (cs.display === 'none' || cs.visibility === 'hidden' || cs.contentVisibility === 'hidden') return false; o *= +cs.opacity; if (o < 0.05) return false; } return true; };
 const islands = [...document.querySelectorAll(ISLANDS)].filter((e) => e.getClientRects().length && shown(e)).map((e) => e.getBoundingClientRect());
 const inside = (x, y, r) => x >= r.left && x <= r.right && y >= r.top && y <= r.bottom;
 const clipped = (el, x, y) => { for (let n = el; n && n !== document.body; n = n.parentElement) { const cs = getComputedStyle(n); if (/(auto|scroll|hidden|clip)/.test(cs.overflow) && !inside(x, y, n.getBoundingClientRect())) return true; } return false; };
 const by = {}, items = {}, w = document.createTreeWalker(document.body, NodeFilter.SHOW_TEXT);
 let total = 0;
 for (let t; (t = w.nextNode());) {
  const el = t.parentElement, words = t.textContent.split(/\s+/).filter((s) => /[\p{L}\p{N}]/u.test(s));
  if (!words.length || !el || el.closest('script,style,title,desc,defs,noscript,textarea,option') || !shown(el)) continue;
  const range = document.createRange(); range.selectNodeContents(t);
  const rect = [...range.getClientRects()].find((r) => r.width > 1 && r.height > 1 && r.right > 0 && r.bottom > 0 && r.left < innerWidth && r.top < innerHeight);
  if (!rect) continue;
  const cx = rect.left + rect.width / 2, cy = rect.top + rect.height / 2;
  if (clipped(el, cx, cy)) continue;
  if (el.closest('#stage') && islands.some((r) => inside(cx, cy, r))) continue;
  const s = (SURF.find(([, sel]) => el.closest(sel)) || ['other'])[0];
  by[s] = (by[s] || 0) + words.length; total += words.length;
  (items[s] = items[s] || []).push(words.join(' '));
 }
 return { total, by, items };
};
window.quietTextAudit = (P, opt = {}) => {
 const BUDGET = Object.assign({ plant: 45, cardRest: 24, cardOpen: 60, queue: 24, hint: 6, status: 10, tag: 0, toast: 10, total: 999 }, opt);
 const out = [], r = quietWords(P);
 if (document.body.classList.contains('alt')) return out;
 for (const [s, max] of Object.entries(BUDGET)) { const n = s === 'total' ? r.total : r.by[s] || 0; if (n > max) out.push(s + ' ' + n + ' > ' + max); }
 const words = (s) => s.split(/\s+/).filter((t) => /[\p{L}\p{N}]/u.test(t));
 const vis = (e) => e.getClientRects().length && getComputedStyle(e).visibility !== 'hidden' && +getComputedStyle(e).opacity > 0.05;
 for (const e of document.querySelectorAll('#chips .chip,.' + P + '-mark')) {
  if (!vis(e)) continue;
  const rd = e.querySelector('.rd'), reading = rd && rd.getClientRects().length ? words(rd.innerText).length : 0, name = words(e.innerText).length - reading;
  if (name > 3) out.push('label "' + e.innerText.replace(/\s+/g, ' ') + '" ' + name + ' > 3');
  if (reading > 5) out.push('reading "' + rd.innerText + '" ' + reading + ' > 5');
 }
 for (const e of document.querySelectorAll('.bl .agent')) { const n = words(e.innerText).length; if (vis(e) && n > 5) out.push('row "' + e.innerText.replace(/\s+/g, ' ') + '" ' + n + ' > 5'); }
 for (const root of document.querySelectorAll('#' + P + '-card,#' + P + '-dock,.chip.' + P + '-bot,.chip.' + P + '-witness')) {
  if (!vis(root)) continue;
  const w = document.createTreeWalker(root, NodeFilter.SHOW_TEXT);
  for (let t; (t = w.nextNode());) {
   const el = t.parentElement;
   if (!el.getClientRects().length || el.closest('kbd,textarea,[data-' + P + '-meta],.' + P + '-kv')) continue;
   let hidden = false; for (let n = el; n && n !== root.parentElement; n = n.parentElement) if (getComputedStyle(n).display === 'none') hidden = true;
   if (hidden) continue;
   for (const tok of words(t.textContent)) if (/\d/.test(tok) && !el.closest('[data-' + P + '-binding]')) out.push('unbound "' + tok + '" in ' + el.outerHTML.slice(0, 120) + ' < ' + (el.parentElement.className || el.parentElement.tagName));
  }
 }
 return out;
};
